diff --git a/lib/parsedate.c b/lib/parsedate.c
index b4dd97b..0b67771 100644
--- a/lib/parsedate.c
+++ b/lib/parsedate.c
@@ -114,6 +114,10 @@ struct tzinfo {

 #define tDAYZONE (-60)         /* offset for daylight savings time */

+/* last single-letter zone name, used to bound the direct array index
+   lookup below */
+#define TZONE_LAST 'Z'
+
 /* alpha-sorted list of single-letter time zones */
 static const struct tzinfo tzone[] = {
   { "A", -1 * 60 },            /* Alpha */
@@ -335,7 +339,7 @@ UNITTEST int checktz(const char *check, size_t len)
     return -1;
   else if(len == 1) {
     /* short-cut single letter names */
-    if((check[0] < 'A') || (check[0] > 'Z') || (check[0] == 'J'))
+    if((check[0] < 'A') || (check[0] > TZONE_LAST) || (check[0] == 'J'))
       return -1; /* no such tz */
     return tzone[check[0] - 'A'].offset * 60;
   }

